    [TestCategory("Coding-Rules")]
    [TestCategory("API - Controllers")]
    [TestClass]
    public class RJIT_CR_API_C_00009 : ControllerTestBase
    {
        [TestMethod]
        public void Controller_Method_Should_Provide_At_Least_One_Error_Status_Code()
        {
            var missingProduceResponseTypes = (from controller in Controllers
                                               from method in controller.Methods
                                               where method.Attributes.Any(a => (a.Arguments.Any(arg => arg.Contains("ProblemDetails")))).IsFalse()
                                               select new
                                               {
                                                   ErrorClass = controller.FullQualifiedName,
                                                   Error = $@"
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Controller: {controller.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
MethodName: {method.Name}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Method:     

{method.MethodValue.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample: 

[ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest)]
{method.MethodValue.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                               }).ToImmutableList();

            Assert.IsTrue(missingProduceResponseTypes.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_API_C_00009

Missing produce response type for Error result. Findings {missingProduceResponseTypes.Count}': {Environment.NewLine}{missingProduceResponseTypes.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }
